package com.fandazi.feature.order;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItemEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private OrderEntity order; @Column(nullable=false) private Long dishId; @Column(nullable=false) private String dishName; @Column(nullable=false) private int quantity; @Column(nullable=false,precision=12,scale=2) private BigDecimal unitPrice; protected OrderItemEntity(){} public OrderItemEntity(OrderEntity order,Long dishId,String dishName,int quantity,BigDecimal unitPrice){this.order=order;this.dishId=dishId;this.dishName=dishName;this.quantity=quantity;this.unitPrice=unitPrice;} public BigDecimal getUnitPrice(){return unitPrice;} }
